cd /tmp/shurik-workspace-T62ibr && cat > /tmp/extract_utt.sh <<'EOF'
#!/bin/bash
# usage: extract_utt.sh <sha>
git show -s --format=%B "$1" | awk '
  state==0 { if ($0 ~ /^Reply-To: /) state=1; next }
  state==1 { if ($0 == "") { state=2; next } }
  state==2 { print }
' | awk 'BEGIN{blank=0} { if ($0=="") { blank++ } else { blank=0 } ; lines[NR]=$0 } END { n=NR; while (n>0 && lines[n]=="") n--; for (i=1;i<=n;i++) print lines[i] }'
EOF
chmod +x /tmp/extract_utt.sh
for pair in "monica:701ff1a55f1c01671ae1ea726ac1a46b05e309fb" "joey:a9a2bc5e9da42011961e4ea51c769c08ce5bc28c" "monica:7ca5d0da7161b92ecfb234759349fb372ebd0dea" "rachel:2d1033e623938f1675618a0843256905daeb2786" "chandler:6a532be8a1a2c8d08f79eea14635a3d49b851c5d" "phoebe:a9437430a885b343f683f2f16516222a9fb78ee4"; do b=${pair%%:*}; s=${pair##*:}; echo "--- $b"; /tmp/extract_utt.sh $s; done
